import pandas as pd
import numpy as np
import itertools

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    """
    Calculate the mean of numerical values in each position across tuples in a list.

    Parameters:
    data_list (list): A list of tuples containing numerical and non-numerical values.

    Returns:
    pd.DataFrame: A DataFrame with one column 'Mean Value' and index 'Position i' for each position.
    """
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Determine the maximum length of tuples to know how many positions we have
    max_len = max(len(t) for t in data_list) if data_list else 0

    if max_len == 0:
        return pd.DataFrame(columns=['Mean Value'])

    # Initialize lists to store numerical values for each position
    position_values = [[] for _ in range(max_len)]

    for tup in data_list:
        for i, val in enumerate(tup):
            # Check if the value is numeric (int, float, or numeric string)
            # We need to check if it's a number type or a string that can be converted to a number
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                position_values[i].append(float(val))
            elif isinstance(val, str):
                try:
                    num_val = float(val)
                    position_values[i].append(num_val)
                except (ValueError, TypeError):
                    pass
            # Ignore other types like lists, dicts, etc.

    # Calculate means for each position
    mean_values = []
    for i in range(max_len):
        if position_values[i]:
            mean_val = np.mean(position_values[i])
            mean_values.append(mean_val)
        else:
            mean_values.append(np.nan)

    # Create DataFrame
    df = pd.DataFrame({
        'Mean Value': mean_values
    }, index=[f'Position {i}' for i in range(max_len)])

    return df

